"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["7630"],{74155(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>u,frontMatter:()=>i,contentTitle:()=>r,toc:()=>c,assets:()=>h});var o=JSON.parse('{"id":"tangfen/falseconcept","title":"","description":"I suddenly realized that the reason Marx is so often misunderstood is that some people can\'t even get the most basic concepts straight. They constantly fuss over pseudo-concepts. Things that could be understood in elementary school -- these people somehow can\'t figure them out, yet have the nerve to discuss Marx. I truly don\'t know what to say about them.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/falseconcept.md","sourceDirName":"tangfen","slug":"/tangfen/falseconcept","permalink":"/en/tangfen/falseconcept","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"falseconcept","title":"","hide_table_of_contents":true,"sidebar_label":"[Dushulang], Mr. Ququ, French Chef, etc. \u2014 please stop perpetuating the pseudo-concept of labor dimensions!"},"sidebar":"tangfenSidebar","previous":{"title":"[Dushulang] and others \u2014 can you not even understand the relationship between labor and labor-power as a commodity?","permalink":"/en/tangfen/workandcommodity"},"next":{"title":"Starting from [Dushulang]\'s reply: please read carefully, don\'t even get other people\'s meaning backwards","permalink":"/en/tangfen/aboutdslreply"}}'),s=n(74848),a=n(28453);let i={id:"falseconcept",title:"",hide_table_of_contents:!0,sidebar_label:"[Dushulang], Mr. Ququ, French Chef, etc. \u2014 please stop perpetuating the pseudo-concept of labor dimensions!"},r='[Dushulang], Ququ Xiansheng, Falanxi Dacai Shifu, and Others: Please Stop Perpetuating the Pseudo-Concept of "Labor Dimension"!',h={},c=[];function l(e){let t={h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"dushulang-ququ-xiansheng-falanxi-dacai-shifu-and-others-please-stop-perpetuating-the-pseudo-concept-of-labor-dimension",children:'[Dushulang], Ququ Xiansheng, Falanxi Dacai Shifu, and Others: Please Stop Perpetuating the Pseudo-Concept of "Labor Dimension"!'})}),"\n",(0,s.jsx)(t.p,{children:"I suddenly realized that the reason Marx is so often misunderstood is that some people can't even get the most basic concepts straight. They constantly fuss over pseudo-concepts. Things that could be understood in elementary school -- these people somehow can't figure them out, yet have the nerve to discuss Marx. I truly don't know what to say about them."}),"\n",(0,s.jsx)(t.p,{children:'Truth doesn\'t depend on having more people on your side. Even if ten thousand people oppose you, so what? Just like the pseudo-concept of "labor dimension" that\'s still being bandied about on the forum. "Labor dimension" is a pseudo-concept, just like "sun dimension." Only from the perspective of measurement do dimensions exist -- for example, lifespan, length, value, and so on. Dimension relates to measurement. For example, regarding the sun, if we examine it from the perspective of time, the dimension of the sun\'s lifespan is the dimension of time; if from the perspective of size, the dimension of the sun\'s volume is the cube of the length dimension. But we cannot say what the dimension of the sun is, because "sun dimension" is a pseudo-concept -- something that simply doesn\'t exist. Similarly, we cannot ask "what is the dimension of labor?" because "labor dimension" is equally a pseudo-concept. Only when examining labor from the perspective of value measurement can we say that the dimension of the value of the labor-power commodity is likewise the currency dimension.'}),"\n",(0,s.jsx)(t.p,{children:"But many people can't even grasp the most basic concepts. Take this [Dushulang] -- today he's still posting threads asking: \"I ask [Tangfen] what the dimension of labor is and what the dimension of currency is. My purpose is clear -- to ask whether these two dimensions are equal. If they're not equal, how can equivalent exchange take place beforehand?\""}),"\n",(0,s.jsx)(t.p,{children:"Where is there such a thing as a \"labor dimension\"? When did labor and currency need to undergo equivalent exchange? What exchanges with currency is the labor-power commodity, not labor. These most basic concepts aren't even straight. Value is created by labor, but creation is not exchange. Just as acceleration originates from force, but does force therefore equal acceleration? When the most fundamental concepts aren't even clear, opposing Marx? Isn't that a joke?"}),"\n",(0,s.jsx)(t.p,{children:'I ask those who either oppose or support Marx to first get clear on several concepts: labor, labor-power, and the labor-power commodity.\nAlso, understand this: it is labor that determines value, not labor that exchanges for value. Exchange requires identical dimensions; determination does not require identical dimensions. Otherwise, if force determines acceleration, does the dimension of force equal the dimension of acceleration? Moreover, there is fundamentally no such thing as a "labor dimension." Please get the basic concepts straight!'})]})}function u(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(l,{...e})}):l(e)}},28453(e,t,n){n.d(t,{R:()=>i,x:()=>r});var o=n(96540);let s={},a=o.createContext(s);function i(e){let t=o.useContext(a);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),o.createElement(a.Provider,{value:t},e.children)}}}]);